export const playerStoryChapters: Record<string, string[]> = {
  "tom-seaver": [
    "Seaver arrived in 1967 after the Mets won a special lottery for his rights, and the feeling around the franchise changed almost immediately. He won Rookie of the Year, made the All-Star team, and gave a team known for losing a true ace to build around. Two years later he won 25 games, earned the Cy Young Award, and led the Miracle Mets all the way to a championship.",
    "He stayed great long after the miracle. There were 200-strikeout seasons, Cy Young Awards in 1973 and 1975, and several painful near-misses at a no-hitter. Then came the Midnight Massacre in 1977, when a fight with management ended with Seaver being traded to Cincinnati. The anger lasted because Mets fans knew the franchise had pushed away the one player it never should have lost.",
    "His return in 1983 was emotional even though the team was not ready to win. By the end of his Mets career, Seaver had 198 wins for the club and had created the standard for every ace who followed. Other Mets have had amazing peaks, but nobody else has carried the identity of the entire franchise quite like Tom Terrific.",
  ],
  "david-wright": [
    "Wright was drafted in 2001 with a pick the Mets received after Mike Hampton left, which makes his story feel like one of those lucky turns the franchise rarely gets. He reached the majors in 2004, started hitting almost at once, and soon joined José Reyes as the homegrown heart of a new contender. From 2005 through 2008, he looked like the complete third baseman: average, power, speed, defense, and a calm way of handling New York.",
    "The team around him fell apart after the collapses of 2007 and 2008, but Wright stayed. Citi Field’s original dimensions hurt his power, the roster kept changing, and he still became captain in 2013. The cruel part was that spinal stenosis arrived just when the Mets finally became good again. He fought back in 2015, homered in his first game off the injured list, and hit a World Series homer at Citi Field.",
    "His final game in 2018 was not about a pennant or a record. It was a full ballpark thanking a player whose body would no longer let him continue. Wright’s numbers place him near the top of almost every Mets hitting list, but the connection went deeper than that. Fans saw him choose the Mets again and again, even when staying was the difficult choice.",
  ],
  "dwight-gooden": [
    "Gooden reached the majors in 1984 at only 19 and made every fifth day feel different. The fastball jumped, the curveball disappeared, and National League hitters struck out 276 times while he won Rookie of the Year. In 1985 he went 24–4 with a 1.53 ERA and 268 strikeouts, one of the greatest pitching seasons baseball has ever seen.",
    "By 1986, Doc was the young star at the front of a champion’s rotation, but his story was already becoming more complicated. The Mets won the World Series, yet Gooden struggled in his Series starts, missed the parade, and later lost time because of drug problems. He still had excellent seasons afterward, including a 19-win year in 1990, but the almost impossible level of 1985 never fully returned.",
    "That is why fans talk about Gooden with both joy and sadness. They remember the strikeouts and the huge K signs hanging at Shea, while also wondering how much more his talent might have produced. His number 16 is retired because the greatness was real, even if the story did not follow the smooth path everyone expected.",
  ],
  "jacob-degrom": [
    "deGrom was a ninth-round draft pick and a former college shortstop, so nobody expected him to become the next great Mets ace. He reached the majors in 2014 with long hair, little hype, and an immediate ability to make major-league hitters uncomfortable. By the end of the year he was Rookie of the Year, and in 2015 he beat Clayton Kershaw and Zack Greinke in the playoffs on the way to the pennant.",
    "His best years were a strange mix of brilliance and frustration. In 2018, deGrom posted a 1.70 ERA while the team often failed to score for him, forcing voters to look past his 10–9 record and give him the Cy Young Award. He won it again in 2019. By 2021 he was throwing harder than ever and producing numbers that barely looked real, but injuries kept interrupting the show.",
    "He left for Texas after 2022, which made the ending feel sudden and unfinished. Still, for nearly a decade, a deGrom start offered the cleanest version of pitching Mets fans had seen since Seaver: power, control, and the feeling that one run might be enough. The lack of team success around some of his best seasons only made fans value the performance more.",
  ],
  "darryl-strawberry": [
    "The Mets drafted Strawberry first overall in 1980 and expected him to become the star of their next good team. He won Rookie of the Year in 1983, just as the franchise began climbing out of the bottom of the standings. His swing looked effortless, but the result could be a ball landing in Shea’s upper deck. He gave the young Mets a kind of power they had never had before.",
    "Strawberry was an All-Star every year from 1984 through 1990. He helped win the 1986 World Series, hit 39 home runs in both 1987 and 1988, and finished second in the 1988 MVP vote. He could steal bases too, which made him more than a one-skill slugger. When he was locked in, there was no hitter in the lineup opponents feared more.",
    "The difficult part is that his Mets story ended too early. Problems away from the field followed him, and he left for Los Angeles after the 1990 season while still in his prime. Fans can celebrate what he did and still wonder what the all-time record book would look like if he had stayed healthy and remained a Met. His retired number honors both the greatness and the lasting bond.",
  ],
  "jerry-koosman": [
    "Koosman arrived for good in 1968 and nearly won Rookie of the Year after going 19–12 with a 2.08 ERA. That season gave the Mets two young starters—Koosman and Seaver—who could match almost anyone. When the team made its miracle run a year later, Koosman was not standing behind Seaver. He was right beside him.",
    "He won Game 2 of the 1969 World Series and then took the ball again in Game 5 with the championship waiting. Koosman pitched a complete game, drove in the tying run with a groundout, and was on the mound when Cleon Jones caught the final out. He helped win another pennant in 1973 and later won 21 games for a 1976 club that did not give him much room for error.",
    "By the time the Mets traded him after 1978, Koosman had spent more than a decade doing heavy work for the franchise. His 140 Mets wins and huge October starts finally received a permanent honor when number 36 was retired. The retirement felt overdue, which is often the case with players who made excellence look steady instead of dramatic.",
  ],
  "jose-reyes": [
    "The Mets signed Reyes as a 16-year-old from the Dominican Republic, and by 2003 he was in the majors at 19. His speed changed the shape of a game. A normal ground ball could become a hit, a ball down the line could become a triple, and a single could turn into a runner on third before the pitcher escaped the inning. The excitement was instant.",
    "Reyes truly broke out in 2005 and 2006, becoming the leadoff spark for a team that won the NL East. He led the league in stolen bases three times and triples four times as a Met, while his friendship with David Wright gave fans two young stars who had grown up together in the organization. Injuries and the collapses of 2007 and 2008 kept that group from winning as much as it should have.",
    "His first Mets run ended in 2011 with the first batting title in team history, followed by a free-agent deal with Miami. He returned in 2016 as a different player and helped a battered club reach the Wild Card Game. The second stay was not the same as the first, but the early Reyes remains unforgettable: the music, the smile, and the sudden rush whenever he took off.",
  ],
  "pete-alonso": [
    "Alonso was a second-round pick in 2016, known for his bat but questioned because of his defense. He forced his way onto the Opening Day roster in 2019 and immediately made every doubt feel small. By the end of his rookie season he had 53 home runs, an MLB rookie record, plus a Home Run Derby title and the Rookie of the Year Award.",
    "The power never became a one-year trick. Alonso kept driving in runs, won another Derby, and set a Mets single-season record with 131 RBI in 2022. He also became one of the most visible voices in the clubhouse. At times his slumps could be ugly and his defense could become a debate, but every at-bat still carried the chance of changing the game with one swing.",
    "That swing came when the Mets needed it most in Milwaukee in 2024. Down to their final two outs in the Wild Card Series, Alonso hit a go-ahead three-run homer that saved the season and changed his own Mets story. He passed Darryl Strawberry in 2025 and finished his Mets run with a club-record 264 homers before leaving for Baltimore.",
  ],
  "edgardo-alfonzo": [
    "The Mets signed Alfonzo out of Venezuela, and he reached the majors in 1995 without the attention that follows a top American draft pick. He slowly became impossible to remove from the lineup. He could handle second base or third, hit near the top or middle of the order, and make the right play without needing to be the loudest person on the field.",
    "His value became clear when the Mets turned into contenders. In the 1999 Division Series opener, Alfonzo hit a grand slam in the ninth inning and later homered again, announcing that the Mets belonged in October. He followed with his best full season in 2000, hitting .324 with 25 home runs while helping the club win the pennant.",
    "Back problems and a move around the infield made his final Mets seasons less smooth, and he left after 2002. Even so, the late-1990s teams do not work without Fonzie doing a little of everything. Fans remember the quiet smile, the steady glove, and the feeling that a big at-bat was in safe hands.",
  ],
  "sid-fernandez": [
    "The Mets acquired Fernandez from the Dodgers before the 1984 season, and his unusual delivery quickly made him one of the hardest pitchers in baseball to square up. Hitters saw a fastball that seemed to rise and a sweeping curve coming from a wide angle. The result was plenty of strikeouts and very few hits, even when walks made his innings more stressful than necessary.",
    "El Sid became an All-Star in 1986 and went 16–6 for the championship team. His most important work came in Game 7 of the World Series, when he entered with the Mets losing and threw three scoreless innings. The lineup finally came back while Fernandez kept Boston from adding on. Without that quiet relief appearance, the famous ending might never happen.",
    "He remained a useful starter into the early 1990s and finished his Mets career with more than 1,400 strikeouts. Because the rotation also included Gooden, Darling, Cone, and Ojeda, Fernandez can get lost in the crowd. Mets fans who watched him know better: on the right night, his fastball looked as unhittable as anyone’s.",
  ],
  "carlos-beltran": [
    "Beltrán signed a seven-year contract after his huge 2004 postseason made him one of baseball’s biggest free agents. His first Mets season was disappointing and included a frightening outfield collision, but 2006 showed the complete player the club had paid for. He hit 41 home runs, drove in 116, played beautiful center field, and helped the Mets run away with the division.",
    "The last pitch of the 2006 NLCS became the image people used to define him: bases loaded, two outs, Wainwright’s curveball, strike three. It was a terrible ending, but Beltrán had already homered three times in that series and produced an MVP-level regular season. In the years that followed, he kept hitting through knee trouble and won three Gold Gloves as a Met.",
    "By 2011, the team was rebuilding and traded him to San Francisco for pitching prospect Zack Wheeler. Beltrán left with excellent Mets numbers, yet appreciation arrived slowly because one frozen moment was easier to remember than six strong seasons. His story deserves the full view: a star center fielder whose calm style sometimes hid just how much he did.",
  ],
  "francisco-lindor": [
    "The Mets traded for Lindor before the 2021 season and immediately signed him to a contract large enough to turn every at-bat into a public vote. The first year was rough. He struggled at the plate, had an awkward thumbs-down controversy with the fans, and learned that New York could turn a bad week into a full debate. He also hit three homers against the Yankees in one unforgettable night, showing the player underneath the noise.",
    "Lindor settled in and became the steady center of the team. He drove in 107 runs in 2022, joined the 30–30 club in 2023, played elite shortstop, and almost never left the lineup. The numbers mattered, but so did the way he faced questions after a loss and kept taking responsibility. Slowly, the expensive newcomer became the leader of the clubhouse.",
    "The 2024 season completed that change. After the Mets’ awful start, Lindor moved to the leadoff spot and carried the team back into the race. His homer in Atlanta clinched a playoff place, and his grand slam against Philadelphia sent the Mets to the NLCS. Those swings turned respect into love and gave his Mets story the October chapter it needed.",
  ],
  "mike-piazza": [
    "Piazza arrived in May 1998 after a strange week in which the Dodgers traded him to Florida and the Marlins quickly sent him to New York. At first, the pressure showed. Fans booed when he struggled, rumors said he might leave, and every at-bat felt like a test. Then he stayed, signed a long-term deal, and became the superstar the Mets had been missing.",
    "His power changed the lineup. Piazza drove the 1999 team to the playoffs, helped win the pennant in 2000, and produced huge home runs that made Shea shake before the ball landed. Even the difficult moments—the broken-bat incident with Roger Clemens and the Subway Series loss—felt enormous because Piazza had made the Mets part of baseball’s main story again.",
    "Nothing, however, carries the weight of September 21, 2001. In the first major sporting event in New York after the attacks, Piazza hit a late go-ahead homer and gave the crowd a moment to release weeks of pain. That home run became bigger than a season. It is why his Mets story belongs to the city as much as it belongs to the record book.",
  ],
  "jon-matlack": [
    "Matlack reached the Mets in 1971 and won Rookie of the Year the next season with a 2.32 ERA. He joined Seaver and Koosman in a rotation that could carry an offense even when runs were hard to find. His smooth delivery did not attract the same attention as Seaver’s power, but the results placed him among the best left-handers in the league.",
    "His finest Mets moment came in the 1973 NLCS. Facing Cincinnati’s powerful lineup, Matlack threw a two-hit shutout in Game 2 and helped the Mets win a series few expected them to survive. He later started three games in the World Series and kept battling as the Mets pushed Oakland all the way to Game 7.",
    "Matlack made three All-Star teams and shared the 1975 All-Star Game MVP award. He was traded after the 1977 season as the franchise entered a long decline, so his Mets career ended without the attention it deserved. Look past the win totals and the story is clear: he was a top-level pitcher trapped on several teams that could not score for him.",
  ],
  "keith-hernandez": [
    "The Mets acquired Hernandez from St. Louis in June 1983, at a time when losing had become normal in Queens. He did not love the trade at first, but his arrival changed the way the young club carried itself. He controlled the strike zone, turned bunts into outs from first base, organized cutoff plays, and expected the players around him to understand the game as well as he did.",
    "By 1984, the Mets had become contenders. Hernandez finished second in the MVP vote that year and remained the adult voice as Strawberry, Gooden, and the rest of the young core grew into stars. In the 1986 World Series, his two-run single started the Game 7 comeback. He later became the first official captain in Mets history alongside Gary Carter.",
    "His playing career ended without an easy goodbye, but his relationship with Mets fans only grew. The television booth introduced his humor and honesty to another generation, while number 17 finally went up at Citi Field. Keith is loved for the mustache and the stories now, but the foundation was serious: he helped teach the Mets how a winning team behaves.",
  ],
  "brandon-nimmo": [
    "The Mets drafted Nimmo in the first round in 2011 even though Wyoming did not have high-school baseball. That unusual path fit a player who never looked exactly like anyone else. He reached the majors in 2016, waited through crowded outfields and injuries, and gradually proved that his patience at the plate was a real weapon rather than a small skill.",
    "Nimmo grew into a leadoff hitter who could work a walk, drive a fastball, and force an outfielder to make a play because he ran hard every time. He also moved from corner outfield to center when the team needed it. After the 2022 season, the Mets gave him a long-term contract, a sign that the organization saw him as part of the core rather than a useful extra piece.",
    "His constant smile could seem almost out of place during the worst Mets moments, but that was part of why fans connected with him. The effort never changed with the score. By the 2024 playoff run, Nimmo was one of the longest-serving players on the roster. The Mets traded him to Texas for Marcus Semien after 2025, closing a ten-season run in Queens.",
  ],
  "howard-johnson": [
    "The Mets traded pitcher Walt Terrell to Detroit for Johnson after the 1984 season. At first, HoJo was a bench player on a crowded roster and had only a small role on the 1986 champions. Once Ray Knight left, third base opened, and Johnson turned that chance into one of the most unusual power-speed peaks in team history.",
    "He reached 30 home runs and 30 stolen bases in 1987, 1989, and 1991. The last of those seasons included 38 homers and 117 RBI, leading the National League in both categories. He switch-hit, ran aggressively, and could carry the offense even as the great 1980s roster began to break apart.",
    "His defense and streaky hitting sometimes frustrated fans, and he played on only one Mets postseason team despite all that production. That helps explain why his peak can be forgotten outside New York. Inside Mets history, three 30–30 seasons speak loudly: HoJo was one of the franchise’s most dangerous offensive players.",
  ],
  "al-leiter": [
    "Leiter joined the Mets in a 1998 trade with the Marlins and immediately became the emotional center of the rotation. He worked slowly, changed speeds, argued with himself, and somehow found a way through long innings. The style could make fans nervous, but it also made his big-game performances feel like acts of stubbornness.",
    "Nothing showed that better than the 1999 regular-season tiebreaker in Cincinnati. With the Mets’ year on the line, Leiter threw a two-hit shutout and sent them into the playoffs. He helped them return in 2000, pitched well in the World Series, and took a tough Game 5 loss after carrying a close game into the ninth inning.",
    "Leiter remained a reliable starter through 2004 and became the first pitcher to defeat all 30 major-league teams. His Mets record was not built on overwhelming stuff; it was built on preparation, competitiveness, and a willingness to take the ball when everyone understood the stakes. That is why his biggest starts are remembered so clearly.",
  ],
  "jeff-mcneil": [
    "McNeil was a 12th-round draft pick who lost time to injuries and did not reach the majors until he was 26. Once he arrived in 2018, he hit too much to send back down. His short swing, quick hands, and ability to use the whole field made him look like a player from another era.",
    "The Mets kept moving him around because he could handle second base, third base, and the outfield. That flexibility helped the roster, even if it sometimes made his own role unclear. He made the All-Star team in 2019, struggled badly in 2021, and then answered with a .326 average and the National League batting title in 2022.",
    "McNeil’s emotions are never hidden. A bad swing can lead to a broken bat, an argument with the grass, or a face every fan recognizes from their own living room. When he is right, though, few players are more fun to watch because every strange pitch seems hittable. The messiness is part of the charm.",
  ],
  "david-cone": [
    "The Mets acquired Cone from Kansas City before the 1987 season in a trade that looked minor at the time. A year later he went 20–3 with a 2.22 ERA, helped the Mets win 100 games, and finished third in the Cy Young vote. His fastball, slider, and fearless attitude made him a perfect fit for the team’s confident personality.",
    "Cone could also bring trouble toward himself. A badly timed newspaper column during the 1988 NLCS gave Los Angeles extra motivation, and some off-field controversies made his Mets years feel busier than the pitching alone. Still, he kept taking the ball and piling up strikeouts. His 19-strikeout shutout on the final day of 1991 was a perfect display of his talent.",
    "The rebuilding Mets traded him to Toronto in 1992, and he helped the Blue Jays win the World Series. More than a decade later he returned for one final season in 2003. That comeback did not last long, but seeing number 16 back on the mound connected two very different eras of Mets baseball.",
  ],
  "john-stearns": [
    "Stearns came to the Mets from Philadelphia in the trade that sent Tug McGraw away after 1974. By 1977 he was an All-Star catcher on a club that had just traded Seaver and lost much of its hope. That setting made his style stand out even more. He played as if every game were personal, no matter how far the team sat from first place.",
    "The Bad Dude made four All-Star teams, controlled the running game, and even stole 25 bases in 1978—an unusual number for a catcher. He was willing to block the plate, collide with runners, and challenge teammates. One famous moment had him shouting that the Mets had a monster on their hands after a young Darryl Strawberry charged into a fight.",
    "Injuries took away most of his seasons after 1981 and kept his career totals from matching his impact. Stearns later worked for the organization as a coach and instructor, passing the same intensity to younger players. His final public appearance at the 2022 Old Timers’ Day, shortly before his death, showed how much the bond still meant.",
  ],
  "john-olerud": [
    "The Mets acquired Olerud from Toronto before the 1997 season for pitcher Robert Person. He immediately gave a developing lineup a calm, patient center. Olerud rarely chased, used the whole field, and made first base look easy. His presence helped the club improve by 17 wins in his first year.",
    "In 1998 he hit .354 with a .447 on-base percentage, setting Mets records at the time and producing one of the finest hitting seasons in franchise history. A year later he joined Alfonzo, Rey Ordóñez, and Robin Ventura in the infield Sports Illustrated called the best ever. Olerud then hit throughout the 1999 postseason, including important at-bats in the long NLCS battle with Atlanta.",
    "The Mets let him leave for Seattle after that season, choosing Todd Zeile at first base while Olerud went home to play near his family. It was understandable and still painful. The 2000 Mets won the pennant without him, but many fans wondered how much stronger the lineup would have looked with his quiet left-handed bat still in the middle.",
  ],
  "lee-mazzilli": [
    "Mazzilli grew up in Brooklyn, became a first-round Mets pick, and reached the majors in 1976 just as the great Seaver era was ending. After the Midnight Massacre, he became the face of a team with very few stars. He could hit, run, play several positions, and give fans at Shea a reason to care during some empty summers.",
    "His biggest early moment came at the 1979 All-Star Game. Mazzilli hit a game-tying home run and later drew the walk that forced in the winning run. The Mets traded him in 1982 as the rebuild moved in a new direction, but his story came back around when he returned during the 1986 season as a veteran bench player.",
    "Mazzilli delivered important pinch hits in the World Series and finally joined the championship celebration fans once hoped he would lead. That ending is what makes his career feel complete. He carried the franchise when it was down, then returned in time to enjoy the winning years he had helped fans wait for.",
  ],
  "kevin-mcreynolds": [
    "McReynolds arrived from San Diego after the 1986 championship in the trade that sent Kevin Mitchell away. He stepped into left field and immediately became a major run producer, driving in 100 runs in 1987. On a team filled with loud characters, his quiet manner was almost impossible not to notice.",
    "His best season came in 1988. McReynolds hit 27 home runs, drove in 99, played strong defense, and stole 21 bases without being caught once. He finished third in the MVP vote as the Mets won 100 games. The unusual perfect stolen-base record showed that he was a smarter and more complete player than the simple ‘power hitter’ label suggested.",
    "Fans sometimes mistook his calm personality for a lack of passion, especially when the team began falling short after 1988. That reputation followed him even while he kept producing. He was traded to Kansas City after 1991, then returned briefly in 1994. His Mets story is a reminder that a player does not have to perform every emotion for the camera to be valuable.",
  ],
  "dave-magadan": [
    "Magadan entered professional baseball with a reputation as a pure hitter after starring at Alabama. He reached the Mets in 1986 and made a sudden impression with four hits in the division-clinching game. On a roster full of stars and big personalities, the rookie looked completely comfortable placing line drives around Shea.",
    "Playing time was not easy to find while Keith Hernandez held first base, so Magadan learned to help at both corner infield spots. His real chance arrived in 1990, when he hit .328 with a .417 on-base percentage. He did not supply the home-run power teams usually wanted from first or third base, but he gave away very few at-bats.",
    "The Mets of the early 1990s became less patient and less successful, and Magadan left after 1992. He never became the face of an era, yet fans who enjoy the craft of hitting remember him clearly. His swing was short, his approach was calm, and the ball kept finding open grass.",
  ],
  "armando-benitez": [
    "Benítez joined the Mets before the 1999 season through a three-team trade and brought exactly what his new club wanted at the back of the bullpen: a fastball that could overwhelm hitters. At his best, he looked nearly untouchable. He struck out batters at a huge rate and eventually moved from setup work into the closer’s job.",
    "He saved 160 games as a Met and reached 40 saves in both 2000 and 2001. Those numbers place him high on the franchise list, but no Mets fan remembers the experience as simple. Benítez allowed painful late runs in the 1999 playoffs and the 2000 World Series, so every dominant stretch seemed to come with fear about the next huge spot.",
    "By 2003, the relationship had worn down and the Mets traded him during the season. His story should not be turned into a joke, because a pitcher does not collect that many saves by accident. It also should not be cleaned up. Benítez was powerful, productive, and often terrifying to watch—with the meaning of terrifying changing from pitch to pitch.",
  ],
  "tug-mcgraw": [
    "McGraw first reached the Mets in 1965 as a young starting pitcher, struggled, and spent time in the minors before returning as a reliever. The new role changed his career. His screwball gave hitters a look they hated, and he became an important part of the bullpen when the Mets won their first championship in 1969.",
    "His name became part of baseball language in 1973. The Mets were injured and buried in last place when Tug began pushing ‘Ya Gotta Believe.’ It could have sounded silly, but then he pitched brilliantly down the stretch and the team climbed all the way to a pennant. He worked multiple innings, escaped jams, and made his confidence contagious.",
    "The Mets traded him to Philadelphia after 1974 in a deal that brought back John Stearns. McGraw later won another championship with the Phillies, but ‘Ya Gotta Believe’ always remained a Mets phrase. His personality captured something true about the franchise: hope works best when it knows how ridiculous it looks and chooses to keep going anyway.",
  ],
  "roger-mcdowell": [
    "McDowell reached the majors in 1985 and immediately gave Davey Johnson a reliever who could pitch more than one inning. He shared the late-game work with Jesse Orosco, sometimes setting up and sometimes closing. In 1986 he went 14–9 with 22 saves, numbers that show just how often the Mets asked him to carry a game through its middle and end.",
    "His most important performance came in the 16-inning clincher against Houston in the NLCS. McDowell threw five scoreless relief innings and even stayed in the game as a runner because the Mets had emptied their bench. The famous clubhouse pranks and hot-foot stories fit the team’s wild image, but none of them mattered without his serious work on the mound.",
    "He remained a key reliever until the Mets traded him and Lenny Dykstra to Philadelphia for Juan Samuel in 1989, one of the deals fans still hate revisiting. McDowell’s Mets career was short compared with Orosco’s, yet it covered the exact years when the club became a powerhouse. He was part of both the chaos and the structure that made those teams work.",
  ],
  "mookie-wilson": [
    "The Mets drafted Wilson in 1977, the same year they traded Seaver and fell into one of the worst periods in team history. By 1980, Mookie was in center field giving fans speed, energy, and a smile they could connect with. He grew with the rebuild and stayed long enough to see the young talent around him become champions.",
    "Wilson moved between center and left field as Lenny Dykstra arrived, but he remained important because of his switch-hitting and ability to create pressure. Then came the tenth inning of World Series Game 6. With two outs and the Mets one strike from elimination, Mookie kept fouling off pitches until a wild pitch tied the game and his ground ball went through Bill Buckner to win it.",
    "The error became famous, but the at-bat belonged to Wilson. He ran hard enough to make the play matter and stayed calm enough to keep the season alive. The Mets traded him to Toronto in 1989, ending a run that connected the empty Shea years to the biggest celebration the ballpark ever saw.",
  ],
  "ray-knight": [
    "Knight came to the Mets in 1984 and struggled so badly in 1985 that the club tried to trade him. No deal happened, and that failure became a gift. He returned in 1986, hit .298, played a fiery third base, and gave a deep lineup one more hitter who was never afraid of a confrontation.",
    "His October became the kind of run that can change how an entire career is remembered. Knight scored the winning run in Game 6 after Mookie Wilson’s grounder went through Buckner. In Game 7, he hit the home run that put the Mets ahead for good and was named World Series MVP.",
    "The ending was strangely quick. Knight and the Mets could not agree on a new contract, so he left for Baltimore after the parade. That makes his story feel frozen in 1986: one season of redemption, one unforgettable trip around the bases, and a player leaving at the exact moment his Mets value could never be higher.",
  ],
  "gary-carter": [
    "The Mets traded four young players to Montreal for Carter after the 1984 season because they believed they were one final star away. In his first game at Shea, Carter hit a walk-off home run in the tenth inning. It was almost too perfect: the smiling veteran catcher had arrived, and the young Mets suddenly looked ready to challenge anyone.",
    "Carter drove in 100 runs in 1985 and again in 1986 while handling a talented, demanding pitching staff. His knees took a beating behind the plate, but he wanted the responsibility. The defining moment came with two outs and nobody on in the tenth inning of World Series Game 6. Carter singled because he refused to make the last out, starting the rally that saved the championship.",
    "His offense declined during the final years of his Mets contract, but the effort never disappeared. Carter entered the Hall of Fame, had number 8 retired by Montreal, and remained deeply tied to the Mets’ greatest modern team. Fans remember the Kid nickname and the smile, but beneath both was a fierce player who treated winning as his job.",
  ],
  "cleon-jones": [
    "Jones signed with the Mets as a teenager and grew from the early losing clubs into the best hitter on a world champion. After several uneven seasons, everything came together in 1969. He hit .340, made the All-Star team, and finished third in the batting race while giving a pitching-heavy team the dangerous bat it needed.",
    "The World Series gave Jones two permanent moments. In Game 5, a pitch bounced near his foot, manager Gil Hodges produced a shoe-polish-marked baseball, and Jones was awarded first base before Donn Clendenon homered. Later, with two outs in the ninth, Jones caught Davey Johnson’s fly ball in left and dropped to one knee as the Mets became champions.",
    "He remained a strong hitter and helped the club win another pennant in 1973, although injuries affected his later years. Jones was released in 1975 after a dispute with manager Yogi Berra, giving his Mets career an uncomfortable ending. The final catch still rises above it all: Cleon Jones owns the exact instant the miracle became complete.",
  ],
  "ed-kranepool": [
    "Kranepool signed with the expansion Mets in 1962 and reached the majors at 17. He was so young that his long career began before the franchise had finished its first season. The early Mets rushed him, sent him up and down, and asked him to learn while the team lost around him.",
    "He became an All-Star in 1965 and later settled into a role at first base. Kranepool homered in Game 3 of the 1969 World Series, giving the original Met a direct part in the championship. As younger players arrived, he adjusted again and became one of the league’s best pinch hitters, batting .486 in that role in 1974.",
    "When he retired after 1979, Kranepool had played 18 seasons and more games in a Mets uniform than anyone. He was there for the Polo Grounds, Shea Stadium, 120 losses, a miracle title, another pennant, and the fall back into last place. Other players reached higher peaks; nobody lived more of the franchise’s early history.",
  ],
  "bud-harrelson": [
    "Harrelson reached the Mets in 1965 and became the shortstop behind the great young pitching staff. He did not hit for power, but he covered ground, turned double plays, and gave Seaver and Koosman the dependable defense they needed. By 1969 he was an All-Star and an important everyday player on the champions.",
    "His toughness became famous during the 1973 NLCS after he joked about Cincinnati’s hitters. Pete Rose slid hard into second, Harrelson stood his ground, and the fight nearly led to a riot at Shea. The image of the smaller Harrelson refusing to back down against Rose captured the spirit of a team that had spent weeks refusing to accept its place in the standings.",
    "Harrelson later returned as a Mets coach and celebrated another championship in 1986. He even managed the club during the difficult 1990 season. That long connection matters: Buddy helped link the two championship teams and remained one of the people most closely tied to the Mets for the rest of his life.",
  ],
  "lenny-dykstra": [
    "The Mets found Dykstra in the 13th round of the 1981 draft, and he reached the majors in 1985 with exactly the attitude that would define him. Nails played fast, swung hard, and acted as if every opponent had personally insulted him. Sharing center field with Mookie Wilson gave the 1986 lineup two very different ways to create trouble.",
    "Dykstra hit a walk-off two-run homer against Houston in Game 3 of the NLCS, saving the Mets from falling behind in the series. After they lost the first two games of the World Series, he led off Game 3 in Boston with another home run. Those swings made him much bigger than his role and helped keep two championship series from turning away.",
    "The Mets traded Dykstra and Roger McDowell to Philadelphia for Juan Samuel in 1989, a deal that aged badly almost at once. Dykstra later became a star with the Phillies, while serious problems after baseball damaged his public image. His Mets chapter is only part of a complicated life, but that chapter was fearless, important, and built for October.",
  ],
  "jerry-grote": [
    "The Mets acquired Grote from Houston before the 1966 season, and he took over behind the plate as the young pitching staff developed. His batting line rarely jumped off the page. His real value showed up in the confidence of the pitchers, the strength of his throwing arm, and the way he controlled a game from his crouch.",
    "Grote caught nearly every kind of important Mets game: Seaver’s near-perfect night, the 1969 pennant race, the World Series championship, and the 1973 run back to October. He made two All-Star teams and developed a reputation for demanding the same focus from everyone around him. Catchers take the physical punishment that lets pitching staffs become famous, and Grote did it for years.",
    "Injuries and the team’s decline reduced his role before he was traded in 1977. Because defense and game-calling are hard to place in a simple box score, Grote can be missed when fans rank the best Mets. Ask the pitchers from those teams, though, and the story becomes much clearer: he was one of the foundations of both pennant winners.",
  ],
  "michael-conforto": [
    "The Mets selected Conforto tenth overall in 2014 and moved him through the minors quickly because his left-handed bat looked ready. He debuted in July 2015, only a year after being drafted, and immediately joined a team racing toward October. By World Series Game 4 he was hitting two home runs on baseball’s biggest stage.",
    "His path after that was not smooth. The Mets sent him back to the minors in 2016, then watched him break out as an All-Star in 2017 before a severe shoulder injury ended the year. Conforto returned to hit 28 homers in 2018 and 33 in 2019, showing the balanced power and patience that had made him a top pick.",
    "The shortened 2020 season was excellent, but 2021 was a frustrating final year filled with slumps and an awkward walk-off hit-by-pitch. He turned down the Mets’ qualifying offer, injured his shoulder, and missed the next season. Conforto never became the lifelong lineup anchor fans once imagined, yet he gave the club several strong years and a rare two-homer World Series game.",
  ],
  "donn-clendenon": [
    "Clendenon arrived from Montreal in the middle of the 1969 pennant race, bringing the kind of right-handed power the Mets did not have enough of. He was already a veteran, and the trade was not treated like the arrival of a superstar. That changed once the Mets reached October. Clendenon fit into the lineup, handled first base, and gave a pitching-heavy team another bat opponents could not simply pitch around.",
    "The 1969 World Series turned him into a Mets legend. He homered in Games 2, 4, and 5 against Baltimore, becoming the first player to hit three home runs in a five-game World Series and winning the MVP Award. His Game 5 homer came right after the famous Cleon Jones shoe-polish play, pulling the Mets back into a game they eventually won. Clendenon kept supplying the swings that made the miracle possible.",
    "He stayed productive after the parade, driving in 97 runs in 1970 and setting a Mets record with seven RBI in one game. The Mets finished third in both 1970 and 1971, and younger first-base options eventually pushed him out of the picture. That ending can make his Mets career look brief, but it misses the point. Clendenon arrived when the pennant was still a dream and left behind the biggest October power performance the young franchise had seen.",
  ],
  "rick-reed": [
    "Reed arrived at spring training in 1997 as a non-roster pitcher with a complicated reputation because he had worked as a replacement player during the 1994–95 strike. He was 32 and had never held a major-league job for long. Then he made the team, filled an opening in the rotation, and quietly became one of the biggest surprises of the season.",
    "He went 13–9 with a 2.89 ERA in 1997 and helped the Mets jump from 71 wins to 88. Reed made the All-Star team in 1998 and stayed in the rotation as the club moved into the playoffs in 1999 and won the pennant in 2000. He did not overpower hitters; he changed speeds, threw strikes, and forced them to beat him.",
    "The Mets traded him to Minnesota during the 2001 season, ending five years that nobody could have predicted when he first entered camp. Fans love prospects because of what they might become. Reed’s story worked in reverse: almost all the expectations were gone, and then a dependable winning pitcher appeared anyway.",
  ],
  "ron-darling": [
    "The Mets acquired Darling from Texas in the 1982 trade for Lee Mazzilli, another move that helped turn the franchise toward its future. He debuted late in 1983 and joined Gooden, Fernandez, and later Ojeda in a rotation filled with different styles. Darling relied on movement and thought as much as raw power, often pitching his way out of problems he had created with walks.",
    "He won 16 games in 1985 and made his only All-Star team. In the 1986 World Series, Darling threw seven scoreless innings in Game 1 and seven more strong innings in Game 4. He pitched better than his Series record looked, but Boston finally reached him in Game 7 before the Mets’ offense mounted its comeback.",
    "Darling remained in the rotation as the championship team slowly came apart and was traded in 1991. Years later, he returned through the television booth and became one of the voices explaining the game to Mets fans every night. The broadcaster is thoughtful because the pitcher had to be; he spent his career studying how to survive each inning.",
  ],
  "tom-glavine": [
    "Glavine signed with the Mets before 2003 after spending his whole career tormenting them with Atlanta. The first year went badly, and many fans wondered whether a longtime rival would ever look right in blue and orange. He adjusted his approach, regained his command, and gradually became the reliable veteran the Mets had expected.",
    "His best Mets season came in 2006, when he won 15 games and helped the club win the division. With injuries damaging the rotation, Glavine started and won the first game of both playoff rounds. In 2007 he earned his 300th career victory, a real honor that came in a Mets uniform.",
    "Then came Game 162. With a playoff place still possible, Glavine allowed seven runs while recording only one out, and the collapse was complete before the afternoon had settled in. He returned to Atlanta after the season. His Mets story has value and achievement, but it ends with one of the hardest innings fans have ever watched—and there is no honest way around it.",
  ],
  "johan-santana": [
    "The Mets traded four prospects to Minnesota for Santana before 2008 and signed him to the largest contract ever given to a pitcher at the time. He arrived as a two-time Cy Young winner expected to push a talented team over the top. Santana did his part, leading the league with a 2.53 ERA while pitching through knee pain.",
    "On the next-to-last day of that season, with the Mets facing elimination, he threw a three-hit shutout on short rest. The team lost the final game at Shea anyway, but the start showed exactly what an ace looks like. Shoulder surgery later cost him the entire 2011 season and left real questions about whether his best days were gone.",
    "On June 1, 2012, Santana answered with the first no-hitter in Mets history. It took 134 pitches, a missed call on Carlos Beltrán’s line drive, and Mike Baxter crashing into the wall to preserve it. Santana was never fully healthy again, which makes the night both glorious and painful. Fans knew the price might be coming and still needed him to finish.",
  ],
  "ra-dickey": [
    "Dickey signed a minor-league deal with the Mets before 2010 after bouncing through several organizations. Born without an important ligament in his elbow, he had watched a first-round career disappear and rebuilt himself around the knuckleball. At 35, he finally found the pitch, team, and opportunity that made everything click.",
    "He was good in his first two Mets seasons and unbelievable in 2012. Dickey threw consecutive one-hitters, worked through a torn muscle, won 20 games, struck out 230, and earned the Cy Young Award. Every start became an experiment: the same strange pitch could float, dive, or jump at the last second, and even Dickey could not fully explain where it was going.",
    "The Mets traded him at the peak of his value to Toronto after the season. That hurt, but the return included Noah Syndergaard and Travis d’Arnaud, two major pieces of the 2015 pennant team. Dickey gave fans an amazing story while he was here, then helped build the next winning club on his way out.",
  ],
  "jesse-orosco": [
    "Orosco entered the Mets organization as the player to be named later in the 1978 trade that sent Jerry Koosman to Minnesota. He struggled as a starter, disappeared back into the minors, and returned as a reliever. By 1983 he had become an All-Star, winning 13 games and saving 17 while handling far more than one inning at a time.",
    "The 1986 postseason turned him into a permanent Mets image. Orosco won three games in the NLCS, recorded the last out of the 16-inning clincher in Houston, and then struck out Marty Barrett to finish the World Series. His glove flew into the air before the rest of the team reached him, freezing the exact second the Mets became champions again.",
    "The Mets traded him after 1987, but Orosco kept pitching until 2003 and set the major-league record for games pitched. That amazing length makes his Mets years look like only the beginning. For the franchise, though, he will always be the man on the mound for two final outs and two celebrations in the same October.",
  ],
  "tommie-agee": [
    "Agee came to the Mets from the White Sox before 1968 after an earlier Rookie of the Year season, but his first year in New York was a disaster. He hit .217 and heard doubts about whether his talent would ever return. In 1969, the answer arrived quickly: Agee became the power-speed center fielder the lineup and defense both needed.",
    "He hit 26 home runs, won a Gold Glove, and even launched a ball into Shea’s upper deck. Game 3 of the World Series made him a legend. Agee homered to lead off the game, then made two extraordinary catches in center—one running into the gap and another diving toward the warning track—that saved several runs behind Gary Gentry and Nolan Ryan.",
    "Agee remained productive through 1970 before injuries slowed him, and the Mets traded him after 1972. His peak in Queens did not last long, but it landed at the perfect time. The Miracle Mets needed a center fielder who could turn certain hits into impossible outs, and for one championship season Agee seemed able to reach everything.",
  ],
  "daniel-murphy": [
    "Murphy was a 13th-round pick who reached the Mets in 2008 and spent years proving his bat belonged while the team searched for his best position. He played left field, first base, second, and third. That movement reflected the full experience: Murphy could line a difficult pitch into the gap and then make a baserunning or fielding mistake that left everyone confused.",
    "By 2014 he was an All-Star and a steady second baseman. Then October 2015 arrived, and steady became historic. Murphy homered in six straight postseason games, taking Clayton Kershaw, Zack Greinke, Jon Lester, and Jake Arrieta deep while carrying the Mets through Los Angeles and Chicago. He won NLCS MVP because there was no other possible choice.",
    "The magic ended in the World Series, where his fielding mistakes joined the team’s late-inning problems. The Mets let him leave, and watching him become an MVP candidate with Washington made the decision hurt even more. Murphy’s story contains all of it: years of useful hitting, two unbelievable weeks, a difficult ending, and the frustration of seeing the best version continue for a rival.",
  ],
  "wally-backman": [
    "The Mets drafted Backman in the first round in 1977, but his path to a regular job took years. By 1984 he had become the left-handed half of a second-base platoon and an ideal hitter near the top of the order. He did not have star power. He made pitchers work, found ways on base, and brought the fight every day.",
    "Backman hit .320 in 1986 while sharing time with Tim Teufel. The platoon allowed Davey Johnson to chase the best matchup, and Backman accepted a role that changed from game to game. In the postseason he kept producing difficult at-bats and scored important runs without needing to be the center of the lineup.",
    "He stayed through 1988 before the Mets traded him to Minnesota. Backman’s value was never captured by home runs or awards. He represented the sharp edge of those teams—the small player willing to crowd the plate, argue, dive, and make a talented roster feel even more unpleasant to face.",
  ],
  "bob-ojeda": [
    "Ojeda arrived from Boston before the 1986 season in a trade that sent Calvin Schiraldi and other young players away. He was expected to strengthen an already good rotation, but the result was even better. Ojeda went 18–5 with a 2.57 ERA and gave the Mets a calm left-hander who attacked the strike zone.",
    "After the Mets lost the first two games of the World Series at Shea, Ojeda started Game 3 in Boston with the season beginning to feel dangerous. He allowed one run in seven innings and brought the Mets back into the series. Schiraldi, the pitcher Boston received in the trade, later allowed key hits in Games 6 and 7—one of those baseball twists that feels written after the fact.",
    "A freak accident with electric hedge clippers badly injured a finger late in 1988 and kept Ojeda out of that postseason. He returned, but never again reached his 1986 level and left after 1990. One brilliant season was enough to change both his career and the Mets’ championship chances.",
  ],
  "curtis-granderson": [
    "Granderson signed a four-year deal before 2014 and had a difficult first season at Citi Field. The park suppressed his power, the team was still rebuilding, and the big free-agent addition hit only .227. Instead of becoming defensive, he kept working and became one of the adults helping a young clubhouse prepare to win.",
    "Moved into the leadoff spot in 2015, Granderson led the Mets with 26 home runs and gave the lineup patient at-bats from Opening Day through October. He homered in the Division Series, drove in runs throughout the NLCS, and hit three more home runs in the World Series. Murphy had the hottest stretch, but Granderson was the hitter who stayed dependable from April to the final game.",
    "He helped another injured Mets team reach the Wild Card Game in 2016 and was traded to the Dodgers during the 2017 selloff. Granderson’s numbers were good, but the affection came from more than production. He treated people well, handled New York honestly, and gave a young contender the kind of steady leadership that is easy to miss until it is gone.",
  ],
  "matt-harvey": [
    "The Mets drafted Harvey seventh overall in 2010 and brought him to the majors in 2012. By the next summer, Harvey Day had become an event. He started the 2013 All-Star Game at Citi Field, came close to a no-hitter more than once, and pitched with a confidence that made a rebuilding team feel important every fifth night.",
    "Tommy John surgery erased 2014, but Harvey returned in 2015 and helped the Mets win the pennant. The season became a constant argument about innings limits, his agent, and how far the team should push a pitcher coming off surgery. Harvey kept taking the ball and was brilliant for eight innings in World Series Game 5. When he demanded the ninth, the crowd agreed. Kansas City’s comeback turned that bravery into heartbreak.",
    "The years after the pennant were harsh. Thoracic outlet surgery weakened his stuff, his relationship with the club broke down, and the Mets designated him for assignment in 2018. Harvey’s peak was short and the fall was public, but neither fact erases what Harvey Day felt like. For a while, one pitcher made a quiet ballpark believe the future had arrived.",
  ],
  "mike-hampton": [
    "The Mets acquired Hampton from Houston before the 2000 season in a major trade designed to finish a contender. His year began awkwardly, including control problems and questions about whether he wanted to be in New York. Once the season settled, he became the durable left-handed starter the rotation needed and won 15 games.",
    "Hampton saved his best pitching for the NLCS against St. Louis. He won Game 1, then threw a three-hit shutout in Game 5 to clinch the pennant at Shea. Across 16 innings in the series, he did not allow a run and earned NLCS MVP. One season in Queens had already produced the biggest result possible short of a championship.",
    "He left for Colorado in free agency and became famous for mentioning the school system when explaining the move, a quote Mets fans turned into a permanent joke. The departure still helped the franchise: the compensation draft pick became David Wright. Hampton delivered a pennant, left immediately, and indirectly helped create the next face of the Mets. That is an unusually full story for one year.",
  ],
  "bernard-gilkey": [
    "Gilkey arrived as a quiet part of the 1996 outfield and turned into one of the most surprising stars of the season. He had already shown flashes in St. Louis, but in New York the bat finally stayed hot for months at a time. His swing had real loft, his running gave the lineup another way to create trouble, and the Mets suddenly had a player opponents could not simply pitch around.",
    "The numbers were enormous: 30 home runs, 117 RBI, an All-Star selection, and a place among the National League’s top hitters. The team itself still lost 91 games, which made the season feel strange. Gilkey was playing like a franchise cornerstone while the organization around him remained stuck between the 1993 collapse and the Piazza-era turnaround.",
    "His Mets peak lasted only one season, but that does not make it a fluke or a footnote. Gilkey gave fans a summer of legitimate excitement when the club badly needed it, and his production helped prove that the next good Mets team could be built around athletic, dangerous position players. The follow-up never matched the breakout, but the 1996 version remains unforgettable.",
  ],
  "lance-johnson": [
    "Johnson was already an established player when the Mets acquired him, but his first season in Queens made him feel like a discovery. He played center field with speed, took aggressive routes, and turned ordinary singles into pressure. The Mets needed someone who could make a rebuilding lineup move, and Johnson did that almost every night.",
    "His 1996 season was a statistical explosion: a .333 average, 21 triples, 50 doubles, 21 home runs, and 50 stolen bases. The combination was so unusual that it became one of the most entertaining individual seasons in club history. He hit line drives into every gap and forced outfielders to make decisions before they were ready.",
    "Injuries shortened his Mets run, which is the frustrating part of the story. A player with that much speed could not afford to lose his legs, and the club moved on before he had a chance to build something longer. Still, for one season Johnson made the Mets faster, louder, and much more watchable. Fans remember him because the game seemed to speed up whenever he reached first base.",
  ],
  "robin-ventura": [
    "Ventura arrived before the 1999 season with a Gold Glove, a disciplined swing, and a reputation for being exactly the kind of professional the Mets needed. He did not come to New York to perform a personality. He took good at-bats, played third base beautifully, and fit into an infield that became one of the strongest defensive groups in the league.",
    "His Mets story changed in the 1999 NLCS. With the bases loaded in the bottom of the 15th inning, Ventura hit a grand slam that won the game—but a mob of teammates stopped him at first base before he could complete the jog. The ‘grand slam single’ became one of the strangest images in postseason history, and Ventura’s calm reaction made it even funnier.",
    "He remained important during the 2000 pennant run and supplied leadership when the roster faced the pressure of New York’s first Subway Series in decades. Ventura was traded after that season, but his place in Mets memory is secure. The swing, the bases, the teammates swarming him, and the fact that he never seemed embarrassed by any of it made him a perfect Mets character.",
  ],
  "juan-soto": [
    "Soto arrived in New York with a résumé that made normal expectations useless. He had already been a World Series champion, an elite on-base hitter, and one of the most feared young bats in baseball. The Mets signed him because they wanted to change their scale, not simply improve one lineup spot. Every at-bat came with the feeling that the franchise had entered a new financial and competitive era.",
    "His game is built on patience that looks almost disrespectful. Soto lets good pitches pass, refuses to chase many bad ones, and then attacks the mistake with a swing that can travel a long way. The walks are part of the drama, not a pause in it. Citi Field fans quickly learned that a nine-pitch at-bat could be as exciting as a home run because Soto was deciding exactly when the pitcher had lost.",
    "The larger Mets story is still being written. A star like Soto raises the expectations for every player and every front-office decision around him. Whether his Queens years end with a championship or another near-miss, he has already changed what the lineup feels like. The Mets no longer look like they are waiting for the next era to begin when number 22 is standing in the box.",
  ],
  "angel-pagan": [
    "Pagan was one of the most watchable Mets during the difficult Citi Field rebuilding years. He had enough power to surprise a pitcher, enough speed to turn a routine ball into a double, and enough athletic ability to make center field feel larger than it was. When the roster around him was thin, his energy gave the team a pulse.",
    "His best Mets stretch came in 2010 and 2011, when he became a regular part of the lineup and produced the kind of all-around play that does not fit neatly into one statistic. He battled injuries, moved between outfield spots, and occasionally made an unbelievable catch look followed by a frustrating mistake. That inconsistency was part of the experience, but so was the sense that something could happen whenever he ran into space.",
    "Pagan was traded to San Francisco after 2011 and helped the Giants win a World Series. Mets fans watched that from a distance, knowing he had been one of the few genuinely fun players on several mediocre clubs. His Queens story never became a championship story, but it remains a useful reminder that rebuilding seasons still need players who make fans want to stay until the ninth inning.",
  ],
  "juan-lagares": [
    "Lagares reached the Mets with a reputation for defense before the bat had caught up. That was enough to make him valuable on teams that often needed every saved run. He took fearless routes in center field, covered huge ground, and threw with enough strength to make runners reconsider trying for an extra base.",
    "In 2014 he won a Gold Glove and became the kind of player pitchers trusted even when his offensive numbers were uneven. The 2015 pennant team used him alongside Yoenis Céspedes and Curtis Granderson, and his defense helped protect a staff that had been assembled to miss bats but could still give up hard contact. Lagares did not need to hit cleanup to matter.",
    "Injuries and a changing roster eventually reduced his role. The Mets hoped his bat would develop into a full-time answer, but the defense remained the part everyone remembered. Fans still talk about his catches because they looked urgent and slightly dangerous, like the ball had no right to stay in his glove. He gave the club a few seasons of real center-field excitement during a difficult transition.",
  ],
  "todd-hundley": [
    "Hundley became the Mets’ catcher during the period between Gary Carter and Mike Piazza, which meant he had to create his own identity. He did it with power. The swing was aggressive, sometimes too aggressive, but when he connected the ball left Shea in a hurry. In 1996 he set a major-league record with 41 home runs by a catcher.",
    "That season made Hundley an All-Star and briefly turned him into the face of a team still looking for direction. Catching every day took a physical toll, and the Mets sometimes asked him to carry more offense than his body could reasonably support. He remained dangerous in the lineup even when the rest of the roster lacked protection around him.",
    "Piazza’s arrival in 1998 changed the franchise and pushed Hundley into a difficult role. He was traded to the Dodgers, and the Mets moved forward with the greatest offensive catcher of the era. That does not erase Hundley’s contribution. He gave fans a powerful, homegrown catcher during a bleak stretch and helped make the position feel exciting again before Piazza took it to another level.",
  ],
  "pedro-martinez": [
    "Martínez arrived before the 2005 season with the reputation of being the best pitcher in baseball. The Mets were trying to become relevant again, and signing him announced that the club was ready to spend on stars rather than simply patch holes. His changeup still looked unfair, his fastball moved, and every start carried the confidence of a pitcher who expected to control the game.",
    "He won 15 games in his first season and helped stabilize a rotation that had been missing an ace. The 2006 club won the division, but Pedro’s body began to betray him. Hip and calf problems limited his innings, and a torn rotator cuff ended his 2007 season after only a handful of starts. The Mets reached the edge of October without the full version of their biggest pitching investment.",
    "His return in 2008 was one of the better emotional moments of the late Shea era. Martínez could not stay healthy enough to become the long-term ace fans imagined, but he gave the Mets leadership, preparation, and a reminder of what elite pitching looked like. The story is shorter than it should have been, which is exactly why the best nights remain so easy to remember.",
  ],
  "frank-viola": [
    "Viola came to the Mets in the middle of the 1989 season as the organization tried to keep its championship window open. He brought a Cy Young Award, a polished changeup, and the calm of a veteran who had already pitched through serious pressure. The Mets needed him to replace some of the innings and authority lost as the 1986 rotation began to break apart.",
    "His best Mets season came in 1990, when he went 20–12 and made the All-Star team. The win total mattered because it showed the Mets still had an ace capable of carrying a rotation, even though the club finished second to Pittsburgh. Viola worked quickly, repeated his delivery, and gave the team a dependable start whenever the schedule threatened to spin out.",
    "The Mets released him after the 1991 season as the roster moved toward a difficult reset. He never became a lifelong Met, but he helped bridge the gap between the powerhouse and the collapse. Fans remember the fast pace, the changeup, and the feeling that every game he started had a chance to become orderly, even when the rest of the franchise was anything but.",
  ],
  "craig-swan": [
    "Swan kept pitching through the emptiest period in Mets history. He arrived as a young starter, learned how to survive without much run support, and eventually became the club’s most dependable ace after Seaver was traded. His fastball and control were good enough to lead the National League in ERA in 1978, even though the team around him finished last.",
    "That 1978 season made Swan an All-Star and showed how much work was hidden inside his calm style. He did not have Seaver’s public mythology or Koosman’s October résumé. He simply took the ball, limited damage, and gave the Mets a chance. In 1984 he helped the rebuilt club return to contention, providing a veteran link between the bad years and the young powerhouse.",
    "Arm trouble and the physical cost of those innings eventually ended his effectiveness. Swan’s win total never matched the quality of his best seasons because so many of his teams could not score. Mets fans who watched him remember something more important: he stayed, competed, and gave the franchise an ace when there were very few reasons to believe in anything else.",
  ],
  "bret-saberhagen": [
    "Saberhagen arrived in a 1994 trade with Kansas City as a former two-time Cy Young winner whose career had been interrupted by injuries. The Mets were trying to become respectable again, and a healthy Saberhagen gave the rotation a level of precision it had been missing. He changed speeds, worked quickly, and made good hitters look as if they had guessed wrong before the pitch arrived.",
    "His strongest Mets stretch came in 1994 and 1995. The strike shortened both seasons, but Saberhagen still gave the club quality innings and helped stabilize a staff that otherwise lacked a clear leader. He was not the same overwhelming pitcher who had dominated the American League in Kansas City, yet the command and competitiveness remained visible whenever his arm allowed him to work normally.",
    "The frustrating part was how often health interrupted the story. The Mets hoped he would anchor the next contender, but his innings came in pieces and the team around him was still rebuilding. Saberhagen left after 1995, leaving behind flashes of the ace he had been and the sense that a healthier body could have changed the middle of the decade for New York.",
  ],
  "max-scherzer": [
    "Scherzer joined the Mets before 2022 with three Cy Young Awards, a fierce reputation, and the expectation that he would lead the first Steve Cohen superteam. His personality matched the assignment. He attacked hitters, challenged umpires, and treated every start as a personal argument. When he was healthy, the Mets looked like the kind of club that should be planning for October.",
    "He went 11–5 with a 2.29 ERA in 2022 and helped the Mets win 101 games. A strained oblique cost him time, and the late collapse against Atlanta pushed the team into the Wild Card round, where San Diego ended the season. Scherzer pitched well enough to remind everyone why he had been signed, but one October loss made the year feel smaller than the regular-season work deserved.",
    "The 2023 season became the breaking point. Injuries and uneven results led to a trade deadline deal with Texas, where Scherzer eventually won another championship. Mets fans never got the postseason run they imagined, yet they did get the full Scherzer experience: brilliant strikeout nights, visible frustration, and a veteran who made every game feel important. The ending was disappointing, not meaningless.",
  ],
  "noah-syndergaard": [
    "Syndergaard arrived in the trade that sent R.A. Dickey to Toronto and quickly became one of the most intimidating young pitchers in baseball. The hair, the nickname, and the triple-digit fastball made him easy to market, but the real appeal was how aggressively he attacked hitters. Alongside deGrom, Harvey, and Matz, he gave the 2015 Mets a rotation that looked built for a long October.",
    "His 2016 season was the peak: 14 wins, a 2.60 ERA, and the feeling that he could overpower anyone when the slider was sharp. He threw seven scoreless innings in the Wild Card Game against San Francisco, but the Mets’ offense could not finish the night. A serious lat injury and then Tommy John surgery interrupted the next two seasons just as his career was reaching its loudest point.",
    "Syndergaard returned in 2019, but the old velocity came and went. The Mets eventually let him leave, and later stops around baseball never fully restored the version Queens had loved. Still, the 2015–16 stretch remains special. Thor made pitching look theatrical, gave the Mets a believable young rotation, and helped turn a rebuild into a pennant before his arm could stay healthy enough to see the whole story through.",
  ],
  "steve-trachsel": [
    "Trachsel’s first months with the Mets were rough enough that fans were ready to move on. He gave up too many runs, worked slowly, and looked like another temporary veteran in a rotation still trying to recover from the end of the Piazza era. Instead, he adjusted and became one of the steadier starters on the early-2000s teams.",
    "His 2003 season was the payoff. Trachsel won 16 games and gave the Mets innings while younger pitchers developed around him. He was not overpowering and never tried to pretend otherwise. His method was to change speeds, keep the ball in the park, and let the defense work. On nights when the Mets needed a game to stop spinning, that approach had real value.",
    "He was eventually traded to the Cubs, where he reached the postseason, but his Mets tenure remains a good example of a player fans appreciate more after he leaves. Trachsel was not a star. He was the starter who took the ball, absorbed innings, and made the middle of the rotation less fragile. That matters on every team, especially one crossing from one era to another.",
  ],
  "john-franco": [
    "Franco arrived as a Brooklyn-born lefty with a heavy changeup and immediately became one of the Mets’ most dependable relievers. He pitched in every kind of season: playoff races, rebuilding years, injuries, ownership changes, and clubhouse arguments. The role changed from closer to setup man to veteran teacher, but the responsibility never did.",
    "He saved 276 games as a Met, made four All-Star teams, and became the emotional anchor of the late-1990s and early-2000s clubs. Franco was not simply the guy who entered in the ninth. He was the player younger teammates trusted, the local connection fans recognized, and eventually the third captain in franchise history. That kind of authority cannot be created by a save total alone.",
    "His final Mets years were interrupted by injuries, but he kept returning because he wanted the relationship to end on his terms. Franco’s career does not include a Mets championship, yet his place in the franchise is secure. He represented loyalty during seasons when loyalty was difficult, and his Brooklyn identity made every home appearance feel personal in a way few players could match.",
  ],
  "edwin-diaz": [
    "Díaz’s first Mets season was so rough that the trade bringing him to New York became a warning about the cost of expectations. Then 2022 arrived and everything changed. The fastball exploded, the slider disappeared below bats, and the first notes of ‘Narco’ became a signal that Citi Field was about to turn the ninth inning into a concert.",
    "He saved 32 games with a 1.31 ERA in 2022 and struck out hitters at a rate that made even good lineups look helpless. The entrance mattered because it matched the performance: a closer who was not hiding from the attention, embracing the noise, and making the crowd part of the pressure. The Mets won 101 games, and Díaz was one of the main reasons late leads felt safe.",
    "A serious knee injury during the 2023 World Baseball Classic cost him the season and created one of the most painful celebrations Mets fans can remember. He returned, rebuilt his dominance, and posted a 1.63 ERA in 2025 before signing with the Dodgers. Díaz’s Mets story is about dominance, recovery, and the rare player whose entrance became as recognizable as his pitch.",
  ],
  "randy-myers": [
    "Myers was a hard-throwing young lefty in the Mets’ deep 1980s bullpen. He did not receive the same attention as Orosco or McDowell, but his power made him useful in a staff that constantly asked relievers to cover difficult innings. He could miss bats, attack left-handed hitters, and give Davey Johnson another arm when a game started to stretch.",
    "He was part of the 1986 championship club and developed into a larger late-inning role after that season. The Mets traded him before his best seasons elsewhere, which is one reason his name can feel like a bridge rather than a finished chapter. His value in New York was tied to the depth around the famous stars; the bullpen did not work without arms like his.",
    "Myers later became an All-Star closer, making the Mets’ decision to move him part of the usual fan debate about which young players were allowed to leave. He is remembered here for the hard fastball, the championship ring, and the sense that the next version of his career was already visible. Not every important Met stayed long enough to become a headline.",
  ],
  "wayne-garrett": [
    "Garrett grew up in the middle of the Mets’ first great teams. He reached the majors as a young third baseman, learned beside Seaver and Koosman, and developed into the kind of player a pitching staff trusted. He did not have huge power, but he worked counts, made the routine play, and kept finding ways to contribute around the stars.",
    "His biggest moments came in October. Garrett hit the go-ahead home run in Game 3 of the 1969 NLCS and homered twice in the 1973 World Series. Those swings mattered because the Mets often won with pressure rather than overwhelming offense. He was willing to take the at-bat that changed a game even when the rest of his stat line looked ordinary.",
    "Garrett stayed through 1976, giving him a direct connection to both pennant teams and the difficult period that followed. He was traded during the 1977 breakup, another reminder that the franchise was dismantling its own history. Fans remember him as a familiar face who was there for the first miracle and the second pennant, even when the standings around him changed completely.",
  ],
  "john-milner": [
    "Milner gave the Mets a powerful left-handed bat just as the first championship core was finding its shape. He could play first base or left field, hit the ball out of Shea, and provide protection behind the best hitters. His game was not flashy, but the lineup looked more dangerous when he was healthy and locked in.",
    "He led the Mets in home runs three straight seasons from 1972 through 1974 and produced a five-hit game as a rookie. In 1973, his power helped an injury-riddled club stay alive long enough for McGraw and Seaver to lead the late charge. Milner was not the face of the pennant, but he was one of the bats that made the comeback possible.",
    "The 1977 trade of Tom Seaver began the breakup, and Milner was part of the group left to navigate the empty years. He was traded later that season, ending a Mets career that had included two pennants and a lot of hard outs. Fans remember him as a strong, useful hitter who never received quite enough credit for how much pressure he took off the stars around him.",
  ],
  "carlos-delgado": [
    "Delgado arrived in 2006 as the cleanup hitter the Mets believed could complete a contender. He brought a patient left-handed swing, serious power, and the calm of a veteran who had already carried lineups in Toronto. The fit was immediate. He hit 38 home runs, drove in 114 runs, and gave pitchers no comfortable place to work around Beltrán and Wright.",
    "His defining single-game performance came in 2008, when he drove in nine runs against the Yankees. The record still belongs to him, and the night felt like a complete Delgado game: patient when he needed to be, aggressive when the pitch arrived, and capable of changing the scoreboard with one swing. His Mets years also included the difficult 2007 collapse and the frustration of a roster that never fully recovered.",
    "A hip injury ended his 2009 season and eventually ended his Mets chapter. Delgado was not the lifelong icon some expected when he signed, but he gave the club four strong seasons and one of its most ridiculous offensive records. The cleanest memory is a left-handed cleanup hitter standing in the box while a full ballpark waited to see how much damage he could do.",
  ],
  "kevin-mitchell": [
    "Mitchell was the young, switch-everything piece of the 1986 Mets. He could play third base, the outfield, and almost any role Davey Johnson needed. His first brief look in 1984 did not announce a star, but his return in 1986 gave the roster another athletic player who could hit the ball hard and make a game feel unstable whenever he got involved.",
    "His most famous Mets moment came in the tenth inning of World Series Game 6. After Gary Carter singled to keep the season alive, Mitchell came off the bench and singled too. He scored the tying run on Bob Stanley’s wild pitch, then watched Ray Knight and Mookie Wilson finish the comeback. Mitchell did not hit the final ball, but the rally needed his at-bat.",
    "The Mets traded him to San Diego for Kevin McReynolds after the championship. Mitchell later won the 1989 MVP with San Francisco, which made the decision feel even more painful in Queens. His Mets career was short, but short does not mean small. He was a champion, a weirdly useful young player, and one of the names permanently attached to the most famous comeback in franchise history.",
  ],
  "al-weis": [
    "Weis was a utility infielder who came to the Mets for defense, flexibility, and the kind of dependable work that rarely earns headlines. He was not expected to become a central part of the 1969 story. For most of the season, his job was to fill in at second base and shortstop, keep the infield steady, and accept whatever role Gil Hodges needed that day.",
    "October changed his reputation forever. Weis hit .455 in the World Series, drove in an important run in Game 2, and hit the tying home run in Game 5—the only home run he hit at Shea during his Mets career. The swing came after Baltimore had controlled the game, and it gave the Mets the opening they needed to take the lead and finish the championship.",
    "His career numbers were modest, which is exactly why the story remains so good. Weis was not a hidden superstar waiting to be discovered; he was a role player who became enormous when the moment demanded it. Mets fans remember him because October occasionally chooses the least obvious hero, and in 1969 that hero kept showing up in a Mets uniform.",
  ],
};

export function getPlayerStoryChapters(slug: string) {
  return playerStoryChapters[slug] ?? [];
}
